    "caseText": "伊藤さんは資産承継を検討している。2024年中、40歳の実子へ現金550万円を贈与した。子は他の贈与を受けておらず、暦年課税・特例贈与財産の税率を適用し、非課税特例はない。課税価格400万円超600万円以下の特例税率は20％・控除30万円、600万円超1,000万円以下は30％・控除90万円。2024年中に相続が開始したと仮定した場合の法定相続人は配偶者と実子2人で、放棄・養子・代襲はない。本人が全額保険料を負担した本人死亡の保険金を相続人が受け取る。自宅敷地は240㎡・評価額4,800万円。配偶者が取得し、特定居住用宅地等の特例要件を満たし、他に適用する宅地はない。",
    "question": "次の説明の適否はどれか。①遺産に係る基礎控除は4800万円である。②与件の敷地全体に80％減額が適用され、課税価格へ算入する敷地価額は960万円になる。③配偶者の法定相続分は子がいるため遺産全体の3分の1である。",
