    "caseText": "会社員の山田さんは老後の資金計画と公的医療保険について相談している。計算資料は2024年度価額で、老齢基礎年金の満額は816,000円。20歳以上60歳未満の納付済相当月数は450月、免除・未納の扱いを別途加算する必要はない。厚生年金の資料：2003年3月以前36月・平均標準報酬月額280,000円、同年4月以後384月・平均標準報酬額420,000円。報酬比例の乗率は順に7.125/1000、5.481/1000。再評価・従前額保障・加給年金・経過的加算は今回の計算対象外。",
    "question": "次の説明の適否の組合せはどれか。①高額療養費は対象となる自己負担の限度額超過部分を支給する制度である。②傷病手当金の支給期間は同一傷病について支給開始日から通算2年である。③個人型確定拠出年金（iDeCo）の本人拠出掛金は小規模企業共済等掛金控除の対象となる。",
    "kind": "choice",
    "answer": 1,
    "explanation": "①○：対象費用の自己負担限度額を超える部分が対象で、自己負担全額ではありません。②×：同一傷病の支給開始から通算1年6か月です。③○：本人のiDeCo掛金は小規模企業共済等掛金控除の対象です。所得区分や保険外費用などの具体的判定は別途必要です。",
