    "caseText": "会社員の田中さんは2024年中に給与収入820万円を得た。給与所得控除の資料は収入×10％＋110万円。所得金額調整控除・特定支出控除は適用なし。家族の控除対象医療費を82万円支払い、その医療費に対応する保険金22万円を受領した。総所得金額等は200万円以上。本人が保険料を全額負担した保険の一時金750万円（正味払込保険料600万円）も受け取った。源泉分離課税の対象ではなく、他の一時所得はない。",
    "question": "次の説明の適否はどれか。①医療費控除は税額から控除額を直接引く制度である。②医療費控除は確定申告で適用を受ける。③医療費を補てんする保険金は、その給付の目的となる医療費まで差し引き、余りを他の医療費からは差し引かない。",
